INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44661, 'Hosea 7:13', 'Hosea', 7, 13, 'افسوس د هغوی په حال! هغوی زه پریښی یم. هغوی به برباد شي، ځکه چې زما په وړاندې یې سرکښي کړې ده. ما غوښتل چې هغوی وژغورم، خو هغوی ماته وفادار نه دي.', 'افسوس د هغوی په حال! هغوی زه پریشی یم. هغوی به برباد شی، جکه چې زما په وراندې یې سرکشی کرې ده. ما غوشتل چې هغوی وژغورم، خو هغوی ماته وفادار نه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_7_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44662, 'Hosea 7:14', 'Hosea', 7, 14, 'هغوی ماته د زړه د اخلاصه دعا نه کوي، خو هغوی په کټونو باندې ژړا او انګولا کوي. کله چې هغوی د غلو دانو او شرابو په خاطر دعا کوي، نو د کافرانو په شان خپل ځانونه غوڅوي. هغوی زما په خلاف سرکښي کوي.', 'هغوی ماته د زره د اخلاصه دعا نه کوی، خو هغوی په کتونو باندې ژرا او انګولا کوی. کله چې هغوی د غلو دانو او شرابو په خاطر دعا کوی، نو د کافرانو په شان خپل جانونه غوچوی. هغوی زما په خلاف سرکشی کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_7_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44663, 'Hosea 7:15', 'Hosea', 7, 15, 'که څه هم ما د هغوی روزنه وکړه او هغوی مې قوي کړل، خو هغوی زما په وړاندې دسیسه جوړه کړه.', 'که چه هم ما د هغوی روزنه وکره او هغوی مې قوی کرل، خو هغوی زما په وراندې دسیسه جوره کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_7_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44664, 'Hosea 7:16', 'Hosea', 7, 16, 'هغوی زما یعنې څښتن تعالی په ځای بې‌وسه بتانو ته رجوع کوي. هغوی د کږې لیندې په شان بې‌اعتباره دي. د هغوی مشران زما په خلاف د غرور نه ډکې خبرې کوي، نو هغوی به په توره باندې مړه شي او مصریان به هغوی پورې خاندي.»', 'هغوی زما یعنې چشتن تعالی په جای بې‌وسه بتانو ته رجوع کوی. هغوی د کزې لیندې په شان بې‌اعتباره دی. د هغوی مشران زما په خلاف د غرور نه دکې خبرې کوی، نو هغوی به په توره باندې مره شی او مصریان به هغوی پورې خاندی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_7_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44665, 'Leviticus 20:1', 'Leviticus', 20, 1, 'څښتن موسی ته وویل:', 'چشتن موسی ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44666, 'Leviticus 20:2', 'Leviticus', 20, 2, '«اسراییلیانو ته ووایه: که ستاسو څخه یو څوک یا کوم پردی کس چې په اسراییلو کې اوسیږي د خپلو ماشومانو څخه کوم ماشوم د مولک بت ته د قربانۍ په توګه وړاندې کړي، هغه باید ووژل شي. د قوم خلک دې هغه سنګسار کړي.', '«اسراییلیانو ته ووایه: که ستاسو چخه یو چوک یا کوم پردی کس چې په اسراییلو کې اوسیزی د خپلو ماشومانو چخه کوم ماشوم د مولک بت ته د قربانی په توګه وراندې کری، هغه باید ووژل شی. د قوم خلک دې هغه سنګسار کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44667, 'Leviticus 20:3', 'Leviticus', 20, 3, 'زه به د هغه کس په خلاف شم او د خپل قوم څخه به یې وشړم، ځکه چې مولک ته د خپلو ماشومانو په قرباني کولو سره یې زما سپېڅلی ځای ناپاک کړی او زما د سپېڅلي نوم سپکاوی یې کړی دی.', 'زه به د هغه کس په خلاف شم او د خپل قوم چخه به یې وشرم، جکه چې مولک ته د خپلو ماشومانو په قربانی کولو سره یې زما سپېچلی جای ناپاک کری او زما د سپېچلی نوم سپکاوی یې کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44668, 'Leviticus 20:4', 'Leviticus', 20, 4, 'کله چې هغه کس داسې کار وکړي او قوم ورباندې خپلې سترګې پټې کړي او هغه کس ونه وژني،', 'کله چې هغه کس داسې کار وکری او قوم ورباندې خپلې سترګې پتې کری او هغه کس ونه وژنی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44669, 'Leviticus 20:5', 'Leviticus', 20, 5, 'نو زه به په خپله د هغه کس، د هغه د ټولې کورنۍ او هغو ټولو په خلاف شم چې د هغه سره یوځای زما سره بې وفایي کوي او د مولک عبادت کوي. زه به هغوی د خپل قوم څخه وشړم.', 'نو زه به په خپله د هغه کس، د هغه د تولې کورنی او هغو تولو په خلاف شم چې د هغه سره یوجای زما سره بې وفایی کوی او د مولک عبادت کوی. زه به هغوی د خپل قوم چخه وشرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44670, 'Leviticus 20:6', 'Leviticus', 20, 6, 'که چېرې تاسو هغو خلکو ته ورشئ چې کوډې کوي یا کولای شي چې د مړو سره خبرې وکړي، نو زه به ستاسو په خلاف شم او تاسې به د خپل قوم څخه وشړم.', 'که چېرې تاسو هغو خلکو ته ورشی چې کودې کوی یا کولای شی چې د مرو سره خبرې وکری، نو زه به ستاسو په خلاف شم او تاسې به د خپل قوم چخه وشرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44671, 'Leviticus 20:7', 'Leviticus', 20, 7, 'خپل ځانونه پاک کړئ او سپېڅلي اوسئ، ځکه چې زه ستاسو څښتن خدای یم.', 'خپل جانونه پاک کری او سپېچلی اوسی، جکه چې زه ستاسو چشتن خدای یم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44672, 'Leviticus 20:8', 'Leviticus', 20, 8, 'زما د فرمانونو څخه پیروي وکړئ. زه څښتن یم چې تاسو پاک او سپېڅلي کوم.', 'زما د فرمانونو چخه پیروی وکری. زه چشتن یم چې تاسو پاک او سپېچلی کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44673, 'Leviticus 20:9', 'Leviticus', 20, 9, 'که چېرې یو څوک خپل پلار یا خپلې مور ته ښکنځلې وکړي، نو هغه باید ووژل شي. نو خون به یې په خپله غاړه وي.', 'که چېرې یو چوک خپل پلار یا خپلې مور ته شکنجلې وکری، نو هغه باید ووژل شی. نو خون به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44674, 'Leviticus 20:10', 'Leviticus', 20, 10, 'که چېرې یو سړی د بل سړي د ښځې سره زنا وکړي، هغه سړی او هغه ښځه دواړه باید ووژل شي.', 'که چېرې یو سری د بل سری د شجې سره زنا وکری، هغه سری او هغه شجه دواره باید ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44675, 'Leviticus 20:11', 'Leviticus', 20, 11, 'که چېرې یو سړی د خپل پلار د ښځو څخه د یوې ښځې سره زنا وکړي، هغه خپل پلار سپکوي، نو هغه سړی او ښځه دواړه باید ووژل شي. خون به یې په خپله غاړه وي.', 'که چېرې یو سری د خپل پلار د شجو چخه د یوې شجې سره زنا وکری، هغه خپل پلار سپکوی، نو هغه سری او شجه دواره باید ووژل شی. خون به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44676, 'Leviticus 20:12', 'Leviticus', 20, 12, 'که چېرې یو سړی د خپلې انږور سره زنا وکړي، هغوی دواړه باید ووژل شي. کوم کار چې هغوی کړی دی، هغه ډېر بد کار دی او خون به یې په خپله غاړه وي.', 'که چېرې یو سری د خپلې انزور سره زنا وکری، هغوی دواره باید ووژل شی. کوم کار چې هغوی کری دی، هغه دېر بد کار دی او خون به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44677, 'Leviticus 20:13', 'Leviticus', 20, 13, 'که چېرې یو سړی د یو بل سړي سره بد کار وکړي، نو هغوی د کرکې وړ کار کړی دی او دواړه باید ووژل شي. خون به یې په خپله غاړه وي.', 'که چېرې یو سری د یو بل سری سره بد کار وکری، نو هغوی د کرکې ور کار کری دی او دواره باید ووژل شی. خون به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44678, 'Leviticus 20:14', 'Leviticus', 20, 14, 'که چېرې یو سړی د یوې انجلۍ او د هغې د مور دواړو سره واده وکړي، نو درې واړه باید د خپل ډېر بد کار له امله وسوځول شي چې مړه شي، ترڅو ستاسو په منځ کې بدکاري نه وي.', 'که چېرې یو سری د یوې انجلی او د هغې د مور دوارو سره واده وکری، نو درې واره باید د خپل دېر بد کار له امله وسوجول شی چې مره شی، ترچو ستاسو په منج کې بدکاری نه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44679, 'Leviticus 20:15', 'Leviticus', 20, 15, 'که چېرې یو سړی د یو حیوان سره جنسي اړیکې ولري، هغه باید د حیوان سره یوځای ووژل شي.', 'که چېرې یو سری د یو حیوان سره جنسی اریکې ولری، هغه باید د حیوان سره یوجای ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44680, 'Leviticus 20:16', 'Leviticus', 20, 16, 'که چېرې یوه ښځه د یو حیوان سره د جنسي اړیکو د لرلو هڅه وکړي، هغه باید د حیوان سره یوځای ووژل شي. خون به یې په خپله غاړه وي.', 'که چېرې یوه شجه د یو حیوان سره د جنسی اریکو د لرلو هچه وکری، هغه باید د حیوان سره یوجای ووژل شی. خون به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44681, 'Leviticus 20:17', 'Leviticus', 20, 17, 'که چېرې یو سړی د خپلې سکه یا ناسکه خور سره واده وکړي، دا یوه رسوایي ده. هغوی باید په عام محضر کې د قوم څخه وشړل شي. هغه د خپلې خور سپکاوی کړی دی او مسوولیت به یې په خپله غاړه وي.', 'که چېرې یو سری د خپلې سکه یا ناسکه خور سره واده وکری، دا یوه رسوایی ده. هغوی باید په عام محضر کې د قوم چخه وشرل شی. هغه د خپلې خور سپکاوی کری دی او مسوولیت به یې په خپله غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44682, 'Leviticus 20:18', 'Leviticus', 20, 18, 'که چېرې یو سړی د یوې ښځې سره د میاشتینۍ ناروغۍ په دوران کې یوځای شي، هغوی دواړه دې د قوم څخه وشړل شي، ځکه چې هغوی د پاکوالي په اړه مقررات مات کړي دي.', 'که چېرې یو سری د یوې شجې سره د میاشتینی ناروغی په دوران کې یوجای شی، هغوی دواره دې د قوم چخه وشرل شی، جکه چې هغوی د پاکوالی په اره مقررات مات کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44683, 'Leviticus 20:19', 'Leviticus', 20, 19, 'د خپلې مور د خور یا د خپل پلار د خور سره زنا مه کوئ، ځکه چې دا کار به د یو نژدې خپلوان سپکاوی وي، د دغه بد کار مسوولیت به ستاسو دواړو په غاړه وي.', 'د خپلې مور د خور یا د خپل پلار د خور سره زنا مه کوی، جکه چې دا کار به د یو نژدې خپلوان سپکاوی وی، د دغه بد کار مسوولیت به ستاسو دوارو په غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44684, 'Leviticus 20:20', 'Leviticus', 20, 20, 'که چېرې یو سړی د خپل تره د ښځې سره زنا کوي هغه خپل تره سپکوي. مسوولیت به د هغوی په غاړه وي، هغوی به بې اولاده پاتې شي.', 'که چېرې یو سری د خپل تره د شجې سره زنا کوی هغه خپل تره سپکوی. مسوولیت به د هغوی په غاره وی، هغوی به بې اولاده پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44685, 'Leviticus 20:21', 'Leviticus', 20, 21, 'که چېرې یو سړی د خپلې ورېندار سره واده وکړي، هغوی به بې اولاده وي. هغه یو ناپاکه کار کړی او د خپل ورور سپکاوی یې کړی دی.»', 'که چېرې یو سری د خپلې ورېندار سره واده وکری، هغوی به بې اولاده وی. هغه یو ناپاکه کار کری او د خپل ورور سپکاوی یې کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44686, 'Leviticus 20:22', 'Leviticus', 20, 22, 'څښتن وویل: «زما د ټولو فرمانونو او قوانینو څخه پیروي وکړئ، ترڅو تاسو د کنعان د ځمکې څخه چې هلته مو راولم، ونه شړم.', 'چشتن وویل: «زما د تولو فرمانونو او قوانینو چخه پیروی وکری، ترچو تاسو د کنعان د جمکې چخه چې هلته مو راولم، ونه شرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44687, 'Leviticus 20:23', 'Leviticus', 20, 23, 'د هغو خلکو د رواجونو څخه پیروي مه کوئ چې هلته اوسیږي او زه یې د دې په خاطر شړم، ترڅو تاسو وکولای شئ هغې خاورې ته ورننوځئ. زه د هغوی څخه د هغوی د ټولو بدو عملونو له امله کرکه کوم.', 'د هغو خلکو د رواجونو چخه پیروی مه کوی چې هلته اوسیزی او زه یې د دې په خاطر شرم، ترچو تاسو وکولای شی هغې خاورې ته ورننوجی. زه د هغوی چخه د هغوی د تولو بدو عملونو له امله کرکه کوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44688, 'Leviticus 20:24', 'Leviticus', 20, 24, 'خو تاسو سره مې د دې غني او حاصلخېزې ځمکې وعده کړې ده، ترڅو هغه ستاسو ملکیت شي او هغه به تاسو ته درکوم. زه ستاسو څښتن خدای یم او تاسو مې د نورو قومونو څخه بېل کړي یئ.', 'خو تاسو سره مې د دې غنی او حاصلخېزې جمکې وعده کرې ده، ترچو هغه ستاسو ملکیت شی او هغه به تاسو ته درکوم. زه ستاسو چشتن خدای یم او تاسو مې د نورو قومونو چخه بېل کری یی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44689, 'Leviticus 20:25', 'Leviticus', 20, 25, 'له دې امله تاسو باید د پاکو او ناپاکو حیواناتو او مرغانو ترمنځ ښکاره فرق وکړئ. هغه حیوانات یا مرغان چې هغه مې ناپاک اعلان کړي دي، مه خورئ. د هغو په خوړلو به ناپاک شئ.', 'له دې امله تاسو باید د پاکو او ناپاکو حیواناتو او مرغانو ترمنج شکاره فرق وکری. هغه حیوانات یا مرغان چې هغه مې ناپاک اعلان کری دی، مه خوری. د هغو په خورلو به ناپاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44690, 'Leviticus 20:26', 'Leviticus', 20, 26, 'تاسو به پاک او سپېڅلي شئ، ځکه چې زه څښتن سپېڅلی یم. ما تاسو د نورو قومونو څخه بېل کړي یئ، ترڅو یوازې زما شئ.', 'تاسو به پاک او سپېچلی شی، جکه چې زه چشتن سپېچلی یم. ما تاسو د نورو قومونو چخه بېل کری یی، ترچو یوازې زما شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_20_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
