(44710, 'Numbers 14:6', 'Numbers', 14, 6, 'د نون زوی یوشع او د یفنه زوی کالیب چې د هغو کسانو څخه وو چې هغه خاوره یې کتلې وه، له خفګانه خپل کالي وشکول', 'د نون زوی یوشع او د یفنه زوی کالیب چې د هغو کسانو چخه وو چې هغه خاوره یې کتلې وه، له خفګانه خپل کالی وشکول', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44711, 'Numbers 14:7', 'Numbers', 14, 7, 'او خلکو ته یې وویل: «هغه ځمکه چې مونږ وکتله هغه ډېره ښه ځمکه ده.', 'او خلکو ته یې وویل: «هغه جمکه چې مونز وکتله هغه دېره شه جمکه ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44712, 'Numbers 14:8', 'Numbers', 14, 8, 'که چېرې خدای زمونږ څخه راضي وي، هغه به مو هلته یوسي او هغه غني او حاصلخېزه ځمکه به راته راکړي.', 'که چېرې خدای زمونز چخه راضی وی، هغه به مو هلته یوسی او هغه غنی او حاصلخېزه جمکه به راته راکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44713, 'Numbers 14:9', 'Numbers', 14, 9, 'نو د څښتن په وړاندې سرکښي مه کوئ او د هغه ځای د خلکو څخه مه وېرېږئ. مونږ به په اسانۍ سره په هغوی باندې بریالي شو. څښتن زمونږ سره مل دی او هغو خدایانو ته یې ماتې ورکړې ده چې د هغوی ساتنه یې کوله. نو مه وېرېږئ.»', 'نو د چشتن په وراندې سرکشی مه کوی او د هغه جای د خلکو چخه مه وېرېزی. مونز به په اسانی سره په هغوی باندې بریالی شو. چشتن زمونز سره مل دی او هغو خدایانو ته یې ماتې ورکرې ده چې د هغوی ساتنه یې کوله. نو مه وېرېزی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44714, 'Numbers 14:10', 'Numbers', 14, 10, 'ټول قوم ګواښ وکړ چې موسی او هارون سنګسار کړي چې مړه شي. خو ناڅاپه د څښتن جلال په سپېڅلې خېمې باندې ټولو اسراییلیانو ته راښکاره شو.', 'تول قوم ګواش وکر چې موسی او هارون سنګسار کری چې مره شی. خو ناچاپه د چشتن جلال په سپېچلې خېمې باندې تولو اسراییلیانو ته راشکاره شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44715, 'Numbers 14:11', 'Numbers', 14, 11, 'څښتن موسی ته وویل: «ترڅو پورې به دا خلک ما نه مني؟ که څه هم ما هغوی ته ډېرې معجزې ښودلې دي، خو بیاهم هغوی په ما باندې باور نه لري.', 'چشتن موسی ته وویل: «ترچو پورې به دا خلک ما نه منی؟ که چه هم ما هغوی ته دېرې معجزې شودلې دی، خو بیاهم هغوی په ما باندې باور نه لری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44716, 'Numbers 14:12', 'Numbers', 14, 12, 'زه به په هغوی باندې وبا نازله کړم او له منځه به یې یوسم، خو ستا څخه به د یو داسې قوم نیکه جوړ کړم چې د هغوی د قوم څخه لوی او قوي وي.»', 'زه به په هغوی باندې وبا نازله کرم او له منجه به یې یوسم، خو ستا چخه به د یو داسې قوم نیکه جور کرم چې د هغوی د قوم چخه لوی او قوی وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44717, 'Numbers 14:13', 'Numbers', 14, 13, 'خو موسی څښتن ته وویل: «تا په خپل قدرت سره دا قوم د مصر څخه راوویست. کله چې مصریان واوري چې تا د خپل قوم سره داسې وکړل،', 'خو موسی چشتن ته وویل: «تا په خپل قدرت سره دا قوم د مصر چخه راوویست. کله چې مصریان واوری چې تا د خپل قوم سره داسې وکرل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44718, 'Numbers 14:14', 'Numbers', 14, 14, 'نو هغوی به دا د کنعان خلکو ته ووایي. دغه خلک له مخکې نه خبر دي چې ته، ای څښتنه زمونږ سره مل یې او کله چې ستا ورېځ زمونږ دپاسه ودریږي، نو مونږ ته مخامخ ښکارې. د ورځې له خوا د ستنې په شان ورېځ کې زمونږ په مخکې ځې او د شپې له خوا د ستنې په شان اور کې.', 'نو هغوی به دا د کنعان خلکو ته ووایی. دغه خلک له مخکې نه خبر دی چې ته، ای چشتنه زمونز سره مل یې او کله چې ستا ورېج زمونز دپاسه ودریزی، نو مونز ته مخامخ شکارې. د ورجې له خوا د ستنې په شان ورېج کې زمونز په مخکې جې او د شپې له خوا د ستنې په شان اور کې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44719, 'Numbers 14:15', 'Numbers', 14, 15, 'اوس که چېرې ته خپل ټول قوم ووژنې، نو هغه قومونه چې ستا د شهرت په هکله یې اورېدلي دي داسې به وایي', 'اوس که چېرې ته خپل تول قوم ووژنې، نو هغه قومونه چې ستا د شهرت په هکله یې اورېدلی دی داسې به وایی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44720, 'Numbers 14:16', 'Numbers', 14, 16, 'چې خپل خلک دې ځکه په دښته کې ووژل چې تا نه شو کولای هغوی هغې ځمکې ته ورولې چې د هغې وعده دې ورسره کړې وه.', 'چې خپل خلک دې جکه په دشته کې ووژل چې تا نه شو کولای هغوی هغې جمکې ته ورولې چې د هغې وعده دې ورسره کرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44721, 'Numbers 14:17', 'Numbers', 14, 17, 'ای څښتنه، مونږ ته دې خپل لوی قدرت وښایه او هغه وعده دې پوره کړه چې کړې دې وه. تا ویلي وو:', 'ای چشتنه، مونز ته دې خپل لوی قدرت وشایه او هغه وعده دې پوره کره چې کرې دې وه. تا ویلی وو:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44722, 'Numbers 14:18', 'Numbers', 14, 18, '‹زه څښتن زر نه په قهرېږم او ډېره مینه او وفاداري کوم او ګناه او سرغړونه بخښم. خو بیاهم اولادونو او لمسیو ته تر درېم او څلورم نسله پورې د هغوی د پلرونو د ګناهونو په خاطر سزا ورکوم.›', '‹زه چشتن زر نه په قهرېزم او دېره مینه او وفاداری کوم او ګناه او سرغرونه بخشم. خو بیاهم اولادونو او لمسیو ته تر درېم او چلورم نسله پورې د هغوی د پلرونو د ګناهونو په خاطر سزا ورکوم.›', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44723, 'Numbers 14:19', 'Numbers', 14, 19, 'ته رحیم یې او ته د خلکو سره ډېر ښه چلند کوې، که څه هم د ښې رویې وړ نه دي. نو مهرباني وکړه دا قوم داسې وبخښه لکه څنګه چې دې له هغه وخته راهیسې بخښلی دی چې هغوی د مصر څخه راووتل.»', 'ته رحیم یې او ته د خلکو سره دېر شه چلند کوې، که چه هم د شې رویې ور نه دی. نو مهربانی وکره دا قوم داسې وبخشه لکه چنګه چې دې له هغه وخته راهیسې بخشلی دی چې هغوی د مصر چخه راووتل.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44724, 'Numbers 14:20', 'Numbers', 14, 20, 'څښتن په ځواب کې وویل: «لکه څنګه چې تا سوال وکړ زه هغوی بخښم.', 'چشتن په جواب کې وویل: «لکه چنګه چې تا سوال وکر زه هغوی بخشم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44725, 'Numbers 14:21', 'Numbers', 14, 21, 'خو زه په خپل ذات او خپل جلال باندې چې ټوله ځمکه ډکوي قسم خورم،', 'خو زه په خپل ذات او خپل جلال باندې چې توله جمکه دکوی قسم خورم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44726, 'Numbers 14:22', 'Numbers', 14, 22, 'د دې خلکو څخه به هېڅوک ژوندی پاتې نه شي چې هغې خاورې ته ورننوځي. هغوی زما جلال او معجزې چې په مصر او دښته کې مې ښودلې وې لیدلې دي، خو هغوی زه څو څو ځلې ازمایلی یم او زما د امر څخه یې سرغړونه کړې ده.', 'د دې خلکو چخه به هېچوک ژوندی پاتې نه شی چې هغې خاورې ته ورننوجی. هغوی زما جلال او معجزې چې په مصر او دشته کې مې شودلې وې لیدلې دی، خو هغوی زه چو چو جلې ازمایلی یم او زما د امر چخه یې سرغرونه کرې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44727, 'Numbers 14:23', 'Numbers', 14, 23, 'هغوی به هېڅکله هغې خاورې ته ورداخل نه شي چې د هغوی د نیکونو سره مې وعده کړې ده. هغه چا چې زه یې نه یم منلی، هغه به هېڅکله هم ورداخل نه شي.', 'هغوی به هېچکله هغې خاورې ته ورداخل نه شی چې د هغوی د نیکونو سره مې وعده کرې ده. هغه چا چې زه یې نه یم منلی، هغه به هېچکله هم ورداخل نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44728, 'Numbers 14:24', 'Numbers', 14, 24, 'خو په دې خاطر چې زما خدمتګار کالیب د نورو په شان نه دی او هغه ماته وفادار پاتې شوی دی، زه به هغه هغې ځمکې ته ورولم چې هغه کتلې وه او هغه ځمکه به د هغه د اولادې ملکیت شي.', 'خو په دې خاطر چې زما خدمتګار کالیب د نورو په شان نه دی او هغه ماته وفادار پاتې شوی دی، زه به هغه هغې جمکې ته ورولم چې هغه کتلې وه او هغه جمکه به د هغه د اولادې ملکیت شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44729, 'Numbers 14:25', 'Numbers', 14, 25, 'څرنګه چې عمالیقیان او کنعانیان په درو کې اوسیږي، نو سهار بېرته راوګرځئ او د سرې بحیرې له لارې د دښتې خواته لاړ شئ.»', 'چرنګه چې عمالیقیان او کنعانیان په درو کې اوسیزی، نو سهار بېرته راوګرجی او د سرې بحیرې له لارې د دشتې خواته لار شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44730, 'Numbers 14:26', 'Numbers', 14, 26, 'څښتن موسی او هارون ته وویل:', 'چشتن موسی او هارون ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44731, 'Numbers 14:27', 'Numbers', 14, 27, '«ترڅو پورې به دا بدکاره قوم زما په ضد شکایت کوي؟ ما دا شکایتونه ډېر واورېدل!', '«ترچو پورې به دا بدکاره قوم زما په ضد شکایت کوی؟ ما دا شکایتونه دېر واورېدل!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44732, 'Numbers 14:28', 'Numbers', 14, 28, 'اوس هغوی ته دغه ځواب ورکړئ: ‹زه په خپل ذات باندې قسم خورم، څه چې تاسو غوښتي دي هماغسې به درباندې وکړم. ما څښتن دا خبرې وکړې.', 'اوس هغوی ته دغه جواب ورکری: ‹زه په خپل ذات باندې قسم خورم، چه چې تاسو غوشتی دی هماغسې به درباندې وکرم. ما چشتن دا خبرې وکرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44733, 'Numbers 14:29', 'Numbers', 14, 29, 'تاسو به مړه شئ او ستاسو مړي به په دې دښته کې خپاره شي. ستاسو څخه به هېڅوک چې عمر یې د شلو کالو څخه زیات وي هغې خاورې ته داخل نه شي، ځکه چې تاسو زما په خلاف شکایت کړی دی.', 'تاسو به مره شی او ستاسو مری به په دې دشته کې خپاره شی. ستاسو چخه به هېچوک چې عمر یې د شلو کالو چخه زیات وی هغې خاورې ته داخل نه شی، جکه چې تاسو زما په خلاف شکایت کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44734, 'Numbers 14:30', 'Numbers', 14, 30, 'ما قسم خوړلی ؤ چې تاسو به هلته واوسېږئ، خو پرته له کالیب او یوشع څخه به نور هېڅوک هلته ژوند ونه کړي.', 'ما قسم خورلی و چې تاسو به هلته واوسېزی، خو پرته له کالیب او یوشع چخه به نور هېچوک هلته ژوند ونه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44735, 'Numbers 14:31', 'Numbers', 14, 31, 'تاسو ویل چې اولادونه به مو اسیران شي، خو زه به هغوی هغې ځمکې ته راولم چې تاسو رد کړې وه او هغه به یې وطن وي.', 'تاسو ویل چې اولادونه به مو اسیران شی، خو زه به هغوی هغې جمکې ته راولم چې تاسو رد کرې وه او هغه به یې وطن وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44736, 'Numbers 14:32', 'Numbers', 14, 32, 'خو تاسو به په دې دښته کې مړه شئ!', 'خو تاسو به په دې دشته کې مره شی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44737, 'Numbers 14:33', 'Numbers', 14, 33, 'ستاسو اولادونه به په دښته کې څلوېښت کاله سرګردانه ګرځي او ستاسو د بې وفایۍ له امله به ځوریږي، ترڅو پورې چې تاسو ټول مړه شئ.', 'ستاسو اولادونه به په دشته کې چلوېشت کاله سرګردانه ګرجی او ستاسو د بې وفایی له امله به جوریزی، ترچو پورې چې تاسو تول مره شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44738, 'Numbers 14:34', 'Numbers', 14, 34, 'تاسو به څلوېښت کاله یعنې هغه څلوېښت ورځې چې تاسو هغه ځمکه کتلې وه د هرې ورځې په ځای به یو کال د خپلې ګناه په خاطر ځورېږئ. تاسو به زما د مخالفت په معنی باندې پوه شئ.', 'تاسو به چلوېشت کاله یعنې هغه چلوېشت ورجې چې تاسو هغه جمکه کتلې وه د هرې ورجې په جای به یو کال د خپلې ګناه په خاطر جورېزی. تاسو به زما د مخالفت په معنی باندې پوه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44739, 'Numbers 14:35', 'Numbers', 14, 35, 'زه قسم خورم چې تاسو بدکاره خلکو سره به چې زما په وړاندې راټول شوي یئ دا کار وکړم. تاسو هر یو به په دښته کې مړه شئ. دا زما یعنې څښتن خبره ده.›»', 'زه قسم خورم چې تاسو بدکاره خلکو سره به چې زما په وراندې راتول شوی یی دا کار وکرم. تاسو هر یو به په دشته کې مره شی. دا زما یعنې چشتن خبره ده.›»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_35.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44740, 'Numbers 14:36', 'Numbers', 14, 36, 'هغو کسانو چې د ځمکې د کتلو دپاره لېږل شوي وو، غلط خبر راوړی ؤ او قوم یې دې ته مجبور کړی ؤ چې د څښتن په ضد شکایت وکړي.', 'هغو کسانو چې د جمکې د کتلو دپاره لېزل شوی وو، غلط خبر راوری و او قوم یې دې ته مجبور کری و چې د چشتن په ضد شکایت وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_36.mp3', 'https://drive.google.com/file/d/1qq9fF9_syybQGKa7lYI11Wl7z3YJLfd7/preview', 1761237843, 1761237843),
(44741, 'Numbers 14:37', 'Numbers', 14, 37, 'نو هغه ورباندې یوه وژونکې ناروغي نازله کړه او هغوی یې ووژل،', 'نو هغه ورباندې یوه وژونکې ناروغی نازله کره او هغوی یې ووژل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_37.mp3', 'https://drive.google.com/file/d/15qWP1dCFxsPmFensIDwB0oBe_ydykqS9/preview', 1761237843, 1761237843),
(44742, 'Numbers 14:38', 'Numbers', 14, 38, 'خو یوشع او کالیب یې ژوندي پرېښودل.', 'خو یوشع او کالیب یې ژوندی پرېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44743, 'Numbers 14:39', 'Numbers', 14, 39, 'کله چې موسی د اسراییلو قوم ته د څښتن پیغام ورساوه، هغوی ډېر غمجن شول.', 'کله چې موسی د اسراییلو قوم ته د چشتن پیغام ورساوه، هغوی دېر غمجن شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_39.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44744, 'Numbers 14:40', 'Numbers', 14, 40, 'نو هغوی سهار وختي پاڅېدل او ځانونه یې تیار کړل چې د کنعان د غرنۍ سیمې په لور روان شي. هغوی وویل: «دا زمونږ ګناه وه چې د څښتن په هکله مو شکایت وکړ. راځئ چې هغې ځمکې ته لاړ شو چې هغه یې راسره وعده کړې ده.»', 'نو هغوی سهار وختی پاچېدل او جانونه یې تیار کرل چې د کنعان د غرنی سیمې په لور روان شی. هغوی وویل: «دا زمونز ګناه وه چې د چشتن په هکله مو شکایت وکر. راجی چې هغې جمکې ته لار شو چې هغه یې راسره وعده کرې ده.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_40.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44745, 'Numbers 14:41', 'Numbers', 14, 41, 'خو موسی په ځواب کې وویل: «بیا ولې د څښتن د امر څخه سرغړونه کوئ؟ تاسو به بریالي نه شئ!', 'خو موسی په جواب کې وویل: «بیا ولې د چشتن د امر چخه سرغرونه کوی؟ تاسو به بریالی نه شی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_41.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44746, 'Numbers 14:42', 'Numbers', 14, 42, 'مه ځئ. څښتن تاسو سره مل نه دی او ستاسو دښمنان به تاسو ته ماتې درکړي.', 'مه جی. چشتن تاسو سره مل نه دی او ستاسو دشمنان به تاسو ته ماتې درکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_42.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44747, 'Numbers 14:43', 'Numbers', 14, 43, 'کله چې تاسو د عمالیقیانو او کنعانیانو سره مخامخ شئ، تاسو به په جګړه کې مړه شئ. څښتن به تاسو سره مل نه وي، ځکه چې تاسو د هغه د پیروۍ څخه انکار کړی دی.»', 'کله چې تاسو د عمالیقیانو او کنعانیانو سره مخامخ شی، تاسو به په جګره کې مره شی. چشتن به تاسو سره مل نه وی، جکه چې تاسو د هغه د پیروی چخه انکار کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_43.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44748, 'Numbers 14:44', 'Numbers', 14, 44, 'خو بیاهم هغوی جرات وکړ چې غرنۍ سیمې ته لاړ شي، که څه هم نه موسی او نه د څښتن د لوظ صندوق ورسره لاړ.', 'خو بیاهم هغوی جرات وکر چې غرنی سیمې ته لار شی، که چه هم نه موسی او نه د چشتن د لوظ صندوق ورسره لار.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_44.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44749, 'Numbers 14:45', 'Numbers', 14, 45, 'عمالیقیان او کنعانیان د غرنۍ سیمې څخه راښکته شول، اسراییلیانو ته یې ماتې ورکړه او د حرمه تر ښاره پورې ورپسې شول.', 'عمالیقیان او کنعانیان د غرنی سیمې چخه راشکته شول، اسراییلیانو ته یې ماتې ورکره او د حرمه تر شاره پورې ورپسې شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_14_45.mp3', 'https://drive.google.com/file/d/1VGGTOQtrLfhmD9ofWQXW2wDrK79Ci5wx/preview', 1761237843, 1761237843),
(44750, 'Exodus 36:1', 'Exodus', 36, 1, 'بزل ییل، اهولیاب او نور کارګران چې څښتن ورته مهارت او پوهه ورکړې ده د څښتن د حکم سره سم به سپېڅلې خېمه جوړه او تیاره کړي.»', 'بزل ییل، اهولیاب او نور کارګران چې چشتن ورته مهارت او پوهه ورکرې ده د چشتن د حکم سره سم به سپېچلې خېمه جوره او تیاره کری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44751, 'Exodus 36:2', 'Exodus', 36, 2, 'بیا موسی بزل ییل او اهولیاب او ټول ماهر خلک چې څښتن ورته توان ورکړی ؤ او غوښتل یې چې کار وکړي، راوغوښتل چې راشي او کار پیل کړي.', 'بیا موسی بزل ییل او اهولیاب او تول ماهر خلک چې چشتن ورته توان ورکری و او غوشتل یې چې کار وکری، راوغوشتل چې راشی او کار پیل کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44752, 'Exodus 36:3', 'Exodus', 36, 3, 'هغوی د موسی څخه هغه ټولې نذرانې چې د اسراییلو خلکو د سپېڅلې خېمې د جوړولو د کار دپاره راوړې وې، واخیستلې. خو خلکو به موسی ته هر سهار د خپلې خوښې نذرانې راوړلې.', 'هغوی د موسی چخه هغه تولې نذرانې چې د اسراییلو خلکو د سپېچلې خېمې د جورولو د کار دپاره راورې وې، واخیستلې. خو خلکو به موسی ته هر سهار د خپلې خوشې نذرانې راورلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44753, 'Exodus 36:4', 'Exodus', 36, 4, 'نو هغو ټولو ماهرو کسبګرو چې په سپېڅلې خېمې باندې یې کار کاوه، خپل کار پرېښود', 'نو هغو تولو ماهرو کسبګرو چې په سپېچلې خېمې باندې یې کار کاوه، خپل کار پرېشود', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44754, 'Exodus 36:5', 'Exodus', 36, 5, 'او موسی ته یې وویل: «د هغه کار دپاره چې څښتن یې حکم کړی دی، خلک له اړتیا نه زیاتې نذرانې راوړي.»', 'او موسی ته یې وویل: «د هغه کار دپاره چې چشتن یې حکم کری دی، خلک له ارتیا نه زیاتې نذرانې راوری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44755, 'Exodus 36:6', 'Exodus', 36, 6, 'بیا موسی حکم وکړ او هغوی دا خبره ټول کمپ ته ورسوله: «هېڅ سړی یا ښځه دې د سپېڅلې خېمې دپاره نور هېڅ شی د نذرانې په توګه نه راوړي.» نو خلک نور د نذرانو د راوړلو څخه منع کړای شول،', 'بیا موسی حکم وکر او هغوی دا خبره تول کمپ ته ورسوله: «هېچ سری یا شجه دې د سپېچلې خېمې دپاره نور هېچ شی د نذرانې په توګه نه راوری.» نو خلک نور د نذرانو د راورلو چخه منع کرای شول،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44756, 'Exodus 36:7', 'Exodus', 36, 7, 'ځکه څه چې مخکې راوړل شوي وو، هغه د ټول کار د سرته رسولو دپاره بس وو.', 'جکه چه چې مخکې راورل شوی وو، هغه د تول کار د سرته رسولو دپاره بس وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_36_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
